{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Emtricitabine had an absolute oral bioavailability of 93% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Lamivudine oral solution had an absolute bioavailability of 87% in fasted patients, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Didanosine had an overall absolute bioavailability of approximately 43% in patients, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple direct absolute oral bioavailability measurements in humans/adults are well above 20% (93%, 87%, 43%), with high assay-transfer scores. Sub-20 didanosine values come from fed or pediatric conditions and are outweighed by more direct fasting/adult absolute measurements, so high is predicted.",
  "evidence_gaps": [
    "Molecule 1 includes a didanosine record (C36) under the FTC label; this provenance conflict was discounted.",
    "Some didanosine records in fed or pediatric conditions report F below 20% (C26, C27, C07), but they are less condition-matched than adult fasting absolute measurements.",
    "Molecule 8 provides only qualitative 'high' bioavailability without a numeric F value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

